entries[114751] = { ["name"] = "Verjüngung des Alchemisten", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nKristallphiole , Teepflanze\nBeim Herstellen dieses Tranks besteht eine Chance, dass Ihr andere Alchemierezepte aus Pandaria entdeckt.\n\nAuf diese Weise entdeckte Rezepte können weitere Rezepte enthüllen, wenn Ihr mit ihnen Gegenstände herstellt.\n85\nBenötigt Alchemie\n(500)\nBenutzen: Stellt 120000 Gesundheit und 1 Mana wieder her. (1 Min Abklingzeit)" }
entries[114752] = { ["name"] = "Meisterlicher Heiltrank", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nKristallphiole , Teepflanze\nBeim Herstellen dieses Gegenstands besteht eine Chance, dass Ihr neue Rezepte erlernt.\n\nDie Anzahl der Rezepte, die Ihr erlernen könnt, hängt von Eurer Alchemiefähigkeitsstufe ab.\n85\nBenutzen: Stellt 120000 Gesundheit wieder her. (1 Min Abklingzeit)" }
