entries[114779] = { ["name"] = "Trank des Glücks", ["text"] = "Wirken in 1.5 sek. 3\nReagenzien:\nKristallphiole , Goldlotus\nBeim Herstellen dieses Trankes besteht eine Chance, dass Ihr neue Rezepte erlernt.\n\nDie Anzahl der Rezepte, die Ihr erlernen könnt, hängt von Eurer Alchemiefähigkeitsstufe ab.\n85\nBenutzen: Gestattet es Euch, manchmal zusätzliche Beute von Monstern in Pandaria zu bekommen. Hält 20 Min. lang an. Dieser Effekt hält über den Tod hinaus an. (20 Min Abklingzeit)" }
entries[114780] = { ["name"] = "Transmutieren: Lebendiger Stahl", ["text"] = "Wirken in 1.5 sek. 1 tag Abklingzeit – 5\nTools: Stein der Weisen\nReagenzien:\nTrilliumbarren (6)\nBeim Durchführen dieser Transmutation besteht eine Chance, dass Ihr neue Rezepte erlernt.\n\nDie Anzahl der Rezepte, die Ihr erlernen könnt, hängt von Eurer Alchemiefähigkeitsstufe ab.\n\nTransmutationen dieser Größenordnung können nur einmal am Tag durchgeführt werden.\nLebendiger Stahl" }
