entries[114794] = { ["name"] = "Dämonischer Zirkel: Teleport", ["text"] = "10% von Grundmana 40 Meter Reichweite\nSofort 30 sek. Abklingzeit\nTeleportiert Euch zu Eurem dämonischen Zirkel und entfernt alle bewegungseinschränkenden Effekte. [ Seelenbrand: Dämonischer Zirkel: Teleport : Seelenbrand:\nErhöht das Bewegungstempo um 50% und macht Euch gegen Bewegungseinschränkungs- und Bewegungsunfähigkeitseffekte immun. Hält 8 Sek. lang an. ]" }
