entries[114797] = { ["name"] = "Flammenwall", ["text"] = "40 Meter Reichweite\nSofort 10 sek. Abklingzeit\nErschafft einen Flammenwall, der allen Gegnern, die sich im Einflussbereich befinden 1000 Schaden zufügt.\n\nDiese Fähigkeit kann im Verlauf von 10 Sek. noch 9-mal aktiviert werden, um weitere Wallsegmente zu platzieren." }
entries[114798] = { ["name"] = "Flammenwall", ["text"] = "40 Meter Reichweite\nSofort\nErschafft einen Flammenwall, der allen Gegnern, die sich im Einflussbereich befinden 1000 Schaden zufügt.\n\nDiese Fähigkeit kann mehrfach aktiviert werden, um weitere Wallsegmente zu platzieren." }
