entries[115069] = { ["name"] = "Der starke Ochse", ["text"] = "Sofort\nVerringert den erlittenen Schaden um 25%, erhöht die Energieregeneration um 10%, verringert die Chance, kritisch getroffen zu werden, um 6%, erhöht die Ausdauer um 20% und ermöglicht es, eintreffenden Schaden zu staffeln.\n\nStaffeln\nIhr steckt körperliche Angriffe weg, sodass Ihr 80% des Schadens sofort erleidet und die verbleibenden 20% auf die folgenden 10 Sek. gestaffelt aufgeteilt werden." }
entries[115070] = { ["name"] = "Die weise Schlange", ["text"] = "Sofort\nErhöht die hervorgerufene Heilung um 20%, ersetzt Eure Energieressource durch Mana, gewährt Euch Trefferwert und Waffenkunde in Höhe von 50% Eurer durch Gegenstände und Effekte erhaltenen Willenskraft.\n\nErhöht Euer durch Gegenstände erhaltenes Tempo um 50%. Eure Angriffskraft entspricht 200% Eurer Zaubermacht und Ihr profitiert nicht mehr von anderen Angriffskraftquellen.\n\nZusätzlich erhaltet Ihr 'Eminenz', wodurch Ihr das am schwersten verletzte Ziel innerhalb von 20 Metern um 25% Eures durch nicht-automatische Angriffe verursachten Schadens heilt." }
entries[115071] = { ["name"] = "A Zandalari Troll?: Ribbon of Souls Fountain" }
entries[115072] = { ["name"] = "Schadensumleitung", ["text"] = "2.5% von Grundmana / 40 Energie\nSofort 15 sek. Abklingzeit\nBenötigt Schlangenstil, Ochsenstil, Tigerstil\nHeilt Euch selbst sofort um [7 * ( 1 * ( 0.898882 * (Haupthand-Min-DPS * [0.75] 1 + 0 ) + (Angriffskraft / 14) - 1))] bis [7 * ( 1 * ( 0.898882 * (Haupthand-Max-DPS * [0.75] 1 + 0 ) + (Angriffskraft / 14) + 1))] und fügt einem Gegner innerhalb von 10 Metern 50% der Heilmenge als Naturschaden zu. Erzeugt 1 Chi." }
entries[115073] = { ["name"] = "Wirbelnde Feuerblüte", ["text"] = "1 Chi 50 Meter Reichweite\nSpontanzauber\nFügt dem ersten Ziel innerhalb von 50 Metern vor Euch [2.1 * ( 1 * 1 * ( 0.898882 * (Haupthand-Min-DPS * 1 + 1 * (Haupthand-Min-DPS / 2) ) + (Angriffskraft / 14) - 1))] bis [2.1 * ( 1 * 1 * ( 0.898882 * (Haupthand-Max-DPS * 1 + 1 * (Haupthand-Max-DPS / 2) ) + (Angriffskraft / 14) + 1))] Feuerschaden zu.\n\nWenn 'Wirbelnde Feuerblüte' weiter als 10 Meter fliegt, wird der Schaden um 50% erhöht und Ihr macht das Ziel 2 Sek. lang bewegungsunfähig." }
entries[115074] = { ["name"] = "Kampfstil", ["text"] = "Die Mönchsfähigkeit 'Hieb' ändert sich abhängig von der ausgerüsteten Waffe und verändert die Kampfbewegungen des Mönchs. Der Schaden und die Ressourcenkosten bleiben gleich." }
entries[115075] = { ["name"] = "Hammerbräuschlag", ["text"] = "50 Meter Reichweite\nSofort\nVersetzt dem ausgewählten Sauren einen Schlag mit gespeicherter Blitzenergie und macht ihn bewegungsunfähig. Eure Freunde können Eurem Ziel einen sofortigen Todesstoß versetzen!" }
