entries[115151] = { ["name"] = "Erneuernder Nebel", ["text"] = "5.85% von Grundmana 40 Meter Reichweite\nSofort 8 sek. Abklingzeit\nBenötigt Schlangenstil\nIhr hüllt das Ziel in heilenden Nebel, der 18 Sek. lang alle 2 Sek. um 0 heilt. Erzeugt 1 Chi.\n\nJedes Mal, wenn 'Erneuernder Nebel' Heilung hervorruft, bewegt sich der Effekt zu dem [ Glyphe 'Erneuernder Nebel' : am weitesten entfernten / nächsten] verletzten Verbündeten innerhalb von 20 Metern. Dieser Effekt kann bis zu 2-mal auftreten." }
