entries[115175] = { ["name"] = "Beruhigender Nebel", ["text"] = "1% von Grundmana , plus 1% pro Sekunde 40 Meter Reichweite\nKanalisiert (Wirken in 8 sek.)\nBenötigt Schlangenstil\nHeilt das Ziel im Verlauf von 8 Sek. um 22212 .\n\nWenn Ihr mit Eurem Zauber 'Beruhigender Nebel' heilt, besteht eine Chance von 30%, 1 Chi zu erzeugen.\n(Procchance: 30%)" }
entries[115176] = { ["name"] = "Zenmeditation", ["text"] = "Kanalisiert (Wirken in 8 sek.) 3 min Abklingzeit\nVerringert sämtlichen erlittenen Schaden um 90% und leitet bis zu 5 Schadenszauber, die auf Gruppen- oder Schlachtzugsmitglieder innerhalb von 30 Metern gewirkt werden, auf Euch um. Hält 8 Sek. lang an.\n\nWenn Ihr Opfer eines Nahkampfangriffs werdet, bricht Eure Meditation ab und der Effekt endet." }
