entries[115178] = { ["name"] = "Wiederbeleben", ["text"] = "20.1% von Grundmana / 50 Energie 40 Meter Reichweite\nWirken in 10 sek.\nBenötigt Schlangenstil, Ochsenstil, Tigerstil\nLässt den Geist in den Körper zurückkehren und bringt ein totes Ziel mit 35% des Maximalwertes für Gesundheit und Mana wieder ins Leben zurück. Kann nicht während des Kampfes verwendet werden." }
