entries[115180] = { ["name"] = "Benebelnde Dämpfe", ["text"] = "20 Energie 40 Meter Reichweite\nSofort\nBenötigt Ochsenstil\nSchleudert ein Fass Eures besten Gebräus, das das Bewegungstempo aller Gegner innerhalb von 8 Metern 15 Sek. lang um 50% verringert. Verursacht ein hohes Maß an Bedrohung.\n\nBetroffene Ziele haben eine Chance von 3%, mit ihren Nahkampfangriffen zu verfehlen und sich stattdessen selbst 1095 Schaden zuzufügen." }
entries[115181] = { ["name"] = "Feuerodem", ["text"] = "2 Chi\nSpontanzauber\nBenötigt Ochsenstil\nBläst dem Gegner einen feurigen Atem entgegen, der allen Zielen innerhalb von 8 Metern vor Euch 1615 Schaden zufügt.\n\nWenn 'Benebelnde Dämpfe' auf dem Ziel aktiv ist, brennt es und erleidet im Verlauf von 8 Sek. zusätzlich 2080 Schaden. [ Glyphe 'Feuerodem' : Desorientiert das Ziel außerdem 3 Sek. lang ]" }
