entries[115189] = { ["name"] = "Erwartung", ["text"] = "Sofort\nWenn einer Eurer Angriffe auf einem Ziel einen Combopunkt erzeugt, auf dem bereits 5 Combopunkte bestehen, erhaltet Ihr eine Aufladung von 'Erwartung'. Dieser Effekt ist bis zu 5-mal stapelbar.\n\nWenn Ihr einen offensiven Finishing-Move gegen ein Ziel ausführt, werden alle vorhandenen Aufladungen von 'Erwartung' aufgezehrt und gewähren Euch eine entsprechende Anzahl Combopunkte." }
entries[115190] = { ["name"] = "Erwartung", ["text"] = "100 Meter Reichweite\nSofort\nWenn einer Eurer Angriffe auf einem Ziel einen Combopunkt erzeugt, auf dem bereits 5 Combopunkte bestehen, erhaltet Ihr eine Aufladung von 'Erwartung'. Dieser Effekt ist bis zu 5-mal stapelbar.\n\nWenn Ihr einen offensiven Finishing-Move gegen ein Ziel ausführt, werden alle vorhandenen Aufladungen von 'Erwartung' aufgezehrt und gewähren Euch eine entsprechende Anzahl Combopunkte." }
entries[115191] = { ["name"] = "Verstohlenheit", ["text"] = "Sofort 6 sek. Abklingzeit\nVerbirgt Euch in den Schatten, wodurch Ihr um Gegner herumschleichen könnt, ohne gesehen zu werden. [ Nachtpirscher : Das Bewegungstempo in der Verstohlenheit ist um 0% erhöht ] Hält an, bis die Aktion abgebrochen wird." }
entries[115192] = { ["name"] = "Trickbetrug", ["text"] = "Sofort\nWenn Ihr aus der Verstohlenheit heraus Schaden verursacht oder in Verstohlenheit angegriffen werdet, endet ihr Effekt nicht sofort, sondern erst 3 Sek. später." }
