entries[115196] = { ["name"] = "Entkräftendes Gift", ["text"] = "100 Meter Reichweite\nSofort\nEine starke Dosis verknüppelnden Gifts verringert das Bewegungstempo des Ziels 12 Sek. lang um 70%." }
entries[115197] = { ["name"] = "Teilparalyse", ["text"] = "Unbegrenzte Reichweite\nSofort\nDas konzentrierte betäubende Gift ruft eine sofortige Paralyse des Unterkörpers des Gegners hervor, wodurch er 4 Sek. lang bewegungsunfähig wird." }
