entries[115294] = { ["name"] = "Manatee", ["text"] = "Kanalisiert (Wirken in 3 sek.)\nBenötigt Schlangenstil\nNebelwirker ( Hotfix - Passivfähigkeit )\nStellt 5% Eures Maximalmanas pro Aufladung 'Manatee' wieder her. Eure Fähigkeit 'Manatee' muss kanalisiert werden und hält pro Aufladung 0.5 Sek. lang an. Wird das Kanalisieren abgebrochen, werden keine Aufladungen verschwendet.\n\nStellt 4% Eures Maximalmanas pro Aufladung 'Manatee' wieder her. Eure Fähigkeit 'Manatee' muss kanalisiert werden und hält pro Aufladung 0.5 Sek. lang an. Wird das Kanalisieren abgebrochen, werden keine Aufladungen verschwendet." }
entries[115295] = { ["name"] = "Schutz", ["text"] = "2 Chi\nSpontanzauber 30 sek. Abklingzeit\nBenötigt Ochsenstil\nIhr schützt Euch vor zukünftigen Angriffen und absorbiert 30 Sek. lang [(Angriffskraft * 1.971) + 14232 ] Schaden.\n\nErhöht sämtliche Heilung, die Ihr auf Euch selbst wirkt, während 'Schutz' aktiv ist, um 30%." }
entries[115297] = { ["name"] = "Seele vertreiben", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerursacht 6 Sek. lang alle 3 Sek. 58500 bis 61500 Schattenschaden. Jedes Mal, wenn 'Seele vertreiben' Schaden verursacht, erzeugt der Zauber eine vertriebene Seele des Ziels. Vertriebene Seelen greifen das nächstgelegene Ziel an, das sie nicht erzeugt hat." }
