entries[115307] = { ["name"] = "Beinarbeit", ["text"] = "Sofort\nBenötigt Ochsenstil\nBraumeistertraining\nRequires Monk (Braumeister)\nRequires level 34 Ihr seid bewandert in den Künsten des Braumeisters, wodurch sich drei Eurer Fähigkeiten verstärken.\n\nStärkendes Gebräu\nErhöht Eure Schadensstaffelung zusätzlich um 20%, während der Effekt anhält.\n\nTigerklaue\n'Tigerklaue' kostet kein Chi mehr und wenn Ihr mit 'Tigerklaue' Schaden verursacht, wird die Absorptionsmenge Eures nächsten Einsatzes von 'Schutz' um 15% erhöht. Hält 30 Sek. lang an.\n\nBlackout-Tritt\nNach Einsatz von 'Blackout-Tritt' erhaltet Ihr den Effekt 'Beinarbeit', der 6 Sek. lang Eure Parierchance um 20% und Eure Schadensstaffelung um zusätzlich 20% erhöht." }
entries[115308] = { ["name"] = "Flüchtiges Gebräu", ["text"] = "Sofort 6 sek. Abklingzeit\nBenötigt Ochsenstil\nErhöht Eure Chance, Nahkampf- und Distanzangriffen auszuweichen, pro Aufladung von 'Flüchtiges Gebräu' 1 Sek. lang um 30% und zehrt sämtliche Aufladungen von 'Flüchtiges Gebräu' auf." }
entries[115309] = { ["name"] = "Vertriebene Seele", ["text"] = "Kanalisiert (Wirken in 0 sek.)\nDie vertriebene Seele findet das nächste Ziel, das sie nicht erschaffen hat, und versucht es anzugreifen." }
entries[115310] = { ["name"] = "Belebung", ["text"] = "7.7% von Grundmana\nSofort 3 min Abklingzeit\nBenötigt Schlangenstil\nHeilt sofort alle Gruppen- und Schlachtzugsmitglieder innerhalb von 100 Metern um 9579 und hebt sämtliche schädlichen Magie-, Gift- und Krankheitseffekte auf." }
entries[115311] = { ["name"] = "Mächtiger Stabhieb", ["text"] = "1 Zufriedenheit Nahkampfreichweite\nSpontanzauber 6 sek. Abklingzeit\nBenötigt Ochsenstil, Tigerstil\nIhr fügt dem Gegner 250% Waffenschaden mit Eurem Stab zu. Dabei greift Ihr mit solcher Wucht an, dass Ihr selbst 20% des verursachten Schadens erleidet.\n\nWenn Ihr diesem Schaden ausweicht oder er vollständig absorbiert wird, erhaltet Ihr 2 Dunkle Macht." }
entries[115313] = { ["name"] = "Statue der Jadeschlange beschwören", ["text"] = "40 Meter Reichweite\nSofort 30 sek. Abklingzeit\nBenötigt Schlangenstil\nNebelwirker ( Hotfix - Passivfähigkeit )\nBeschwört eine Statue der Jadeschlange am Zielort, die 15 Min. lang anhält. Es kann immer nur jeweils eine Statue der Jadeschlange beschworen werden.\n\nEminenz (Passiv)\nWenn der Mönch Schaden mit nicht-automatischen Angriffen verursacht, heilt seine beschworene Statue der Jadeschlange das am schwersten verletzte Ziel innerhalb von 20 Metern um 42% des verursachten Schadens.\n\nGunst der Schlange (Passiv)\nWenn Ihr 'Beruhigender Nebel' wirkt, wird die Statue ebenfalls 'Beruhigender Nebel' auf einen verletzten Verbündeten innerhalb von 40 Metern wirken.\n\nBeschwört eine Statue der Jadeschlange am Zielort, die 15 Min. lang anhält. Es kann immer nur jeweils eine Statue der Jadeschlange beschworen werden.\n\nEminenz (Passiv)\nWenn der Mönch Schaden mit nicht-automatischen Angriffen verursacht, heilt seine beschworene Statue der Jadeschlange das am schwersten verletzte Ziel innerhalb von 20 Metern um 25% des verursachten Schadens.\n\nGunst der Schlange (Passiv)\nWenn Ihr 'Beruhigender Nebel' wirkt, wird die Statue ebenfalls 'Beruhigender Nebel' auf einen verletzten Verbündeten innerhalb von 40 Metern wirken." }
entries[115314] = { ["name"] = "Glyphe 'Illumination'", ["text"] = "Sofort\nWenn Ihr mit Eurem Zauber 'Heiliger Schock' einen kritischen Effekt erzielt, regeneriert Ihr sofort 1% Eures maximalen Manas." }
entries[115315] = { ["name"] = "Statue des Schwarzen Ochsen beschwören", ["text"] = "40 Meter Reichweite\nSofort 30 sek. Abklingzeit\nBenötigt Ochsenstil\nBeschwört eine Statue des Schwarzen Ochsen am Zielort, die 15 Min. lang anhält. Es kann immer nur jeweils eine Statue des Schwarzen Ochsen beschworen werden.\n\nDie Statue reagiert auf Eure Fähigkeiten 'Provokation' und 'Stieren des Ochsen'.\n\nObhut des Ochsen (Passiv)\nJedes Mal, wenn der Mönch (Angriffskraft * 16) Schaden verursacht, wirkt die Statue des Schwarzen Ochsen 'Schutz' auf ein verletztes Gruppen- oder Schlachtzugsmitglied innerhalb von 40 Metern, der 30 Sek. lang [((Angriffskraft * 1.971) + 14232 ) * 1 ] Schaden absorbiert. Dieser Effekt kann nicht auf den Mönch gewirkt werden." }
