entries[115356] = { ["name"] = "Gewitterschlag", ["text"] = "9.372% von Grundmana 30 Meter Reichweite\nSofort 8 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nVerstärkung ( Hotfix - Passivfähigkeit )\nSchleudert einen Blitz auf einen Gegner, fügt ihm Naturschaden in Höhe von 450% Waffenschaden zu und gewährt Euch 15 Sek. lang eine zusätzliche Chance von 95%, einen Gegner mit Euren Zaubern 'Blitzschlag', 'Kettenblitzschlag', 'Blitzschlagschild' und 'Erdschock' kritisch zu treffen.\n\nElementar, Wiederherstellung\nSchleudert einen Blitz auf einen Gegner, fügt ihm Naturschaden in Höhe von 380% Waffenschaden zu und gewährt Euch 15 Sek. lang eine zusätzliche Chance von 25%, einen Gegner mit Euren Zaubern 'Blitzschlag', 'Kettenblitzschlag', 'Blitzschlagschild' [ Elementarschlag : 'Erdschock' und 'Elementarschlag' / und 'Erdschock'] kritisch zu treffen." }
