entries[116010] = { ["name"] = "Jadelichtgift", ["text"] = "20 Meter Reichweite\nWirken in 1.5 sek. 5 sek. Abklingzeit\nVergiftet einen Gegner. Verursacht so 10 Sek. lang alle 3 Sek. Naturschaden und erhöht jeglichen verursachten Schaden um 25%. Dieser Effekt ist bis zu 4-mal stapelbar." }
entries[116011] = { ["name"] = "Rune der Kraft", ["text"] = "Ersetzt Hervorrufung\n30 Meter Reichweite\nWirken in 1.5 sek.\nPlatziert eine Rune der Kraft auf dem Boden, die 1 Min. lang anhält. Während Ihr Euch innerhalb von 5 Metern Entfernung von Eurer Rune aufhaltet, ist Eure Manaregeneration um 75% und Euer Zauberschaden um 15% erhöht. Es können nur 2 Runen der Kraft gleichzeitig platziert werden. [ Glyphe 'Hervorrufung' : Während Ihr Euch im Effektbereich Eurer Rune aufhaltet, regeneriert Ihr pro Sekunde 1% Eurer maximalen Gesundheit ]\nErsetzt 'Hervorrufung'." }
